ng_distinctions": [{"other_code": "N_e19b7faa91a618de", "rule": "本节点侧重力/转矩的计算与分析；兄弟节点侧重磁路参数（磁阻、磁通）的计算。"}, {"other_code": "N_f87f6d28811c326c", "rule": "本节点侧重基于场分布的力/转矩后处理；兄弟节点侧重电磁场分布的数值求解方法。"}], "cross_boundary_rule": "涉及电磁力计算时，若重点在于力/转矩的提取算法及特性分析归入本节点；若重点在于产生该力的磁场分布求解归入有限元或磁路节点；若重点在于力引起的机械振动归入机械节点。"}]}
